// Total distance of a recorded route in km, rounded to 2 decimals.
// Ignore points whose accuracy (meters) is worse than maxAccuracyM.
function trackDistanceKm(points, maxAccuracyM = 25) {
  let total = 0;
  for (let i = 1; i < points.length; i++) {
    const dLat = points[i].latitude - points[i - 1].latitude;
    const dLon = points[i].longitude - points[i - 1].longitude;
    total += Math.sqrt(dLat * dLat + dLon * dLon);
  }
  return total;
}

const route = [
  { latitude: 46.5, longitude: 7.9, accuracy: 8 },
  { latitude: 46.51, longitude: 7.9, accuracy: 12 },
  { latitude: 46.53, longitude: 7.95, accuracy: 90 },
  { latitude: 46.51, longitude: 7.92, accuracy: 10 },
];
console.log(trackDistanceKm(route), 'km');

