const EARTH_RADIUS_KM = 6371;
const toRad = (deg) => (deg * Math.PI) / 180;

function haversineKm(a, b) {
  const dLat = toRad(b.latitude - a.latitude);
  const dLon = toRad(b.longitude - a.longitude);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.latitude)) * Math.cos(toRad(b.latitude)) * Math.sin(dLon / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(h));
}

function trackDistanceKm(points, maxAccuracyM = 25) {
  const good = points.filter((p) => p.accuracy == null || p.accuracy <= maxAccuracyM);
  let total = 0;
  for (let i = 1; i < good.length; i++) total += haversineKm(good[i - 1], good[i]);
  return Math.round(total * 100) / 100;
}

const route = [
  { latitude: 46.5, longitude: 7.9, accuracy: 8 },
  { latitude: 46.51, longitude: 7.9, accuracy: 12 },
  { latitude: 46.53, longitude: 7.95, accuracy: 90 },
  { latitude: 46.51, longitude: 7.92, accuracy: 10 },
];
console.log(trackDistanceKm(route), 'km');
